{"query": "WITH edges AS (
  SELECT DISTINCT
    CASE WHEN ensembl_gene_id_1 < ensembl_gene_id_2 THEN ensembl_gene_id_1 ELSE ensembl_gene_id_2 END AS a,
    CASE WHEN ensembl_gene_id_1 < ensembl_gene_id_2 THEN ensembl_gene_id_2 ELSE ensembl_gene_id_1 END AS b
  FROM interaction_consensus
  WHERE ensembl_gene_id_1 <> ensembl_gene_id_2
), valid_edges AS (
  SELECT e.a, e.b FROM edges e
  JOIN proteinatlas p1 ON p1.Ensembl = e.a
  JOIN proteinatlas p2 ON p2.Ensembl = e.b
), deg AS (
  SELECT gene, COUNT(*) AS deg FROM (
    SELECT a AS gene FROM valid_edges UNION ALL SELECT b AS gene FROM valid_edges
  ) t GROUP BY gene
)
SELECT gene, deg FROM deg WHERE gene IN ('ENSG00000146648','ENSG00000141736','ENSG00000105976')"}
